  "between {a} and {b} times": { es: "entre {a} y {b} veces", ar: "بين {a} و{b} مرات", zh: "{a} 到 {b} 次", sw: "kati ya mara {a} na {b}", sv: "mellan {a} och {b} gånger", de: "zwischen {a}- und {b}-mal", pt: "entre {a} e {b} vezes", fr: "entre {a} et {b} fois" },
